import{_ as s,o as n,a as p,b as t}from"./app.DKoEZOcr.js";const l="/ascendc.github.io/pr/5487/assets/load2d_gm2l1_demo.bDX_JKLJ.png",u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵计算的搬入","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/cube_compute_load"},{"text":"LoadData（GMToL1-2D矩阵搬运）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/LoadData_GMToL1_2D"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/LoadData_GMToL1_2D.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/LoadData_GMToL1_2D.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),c={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_load/LoadData_GMToL1_2D.md"};function i(e,a,d,r,o,_){return n(),p("div",null,[...a[0]||(a[0]=[t(`<div><article class="markdown-body"><h1>LoadData（GMToL1-2D矩阵搬运）<a id="ZH-CN_TOPIC_0000002538231138"></a></h1><h2 id="产品支持情况">产品支持情况<a id="zh-cn_topic_0000002567745223_section796754519912"></a><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：支持</li></ul></div><div data-filter="x90"><ul><li>Kirin X90：支持</li></ul></div><div data-filter="9030"><ul><li>Kirin 9030：支持</li></ul></div><h2 id="功能说明">功能说明<a id="zh-cn_topic_0000002567745223_section106841136114319"></a><a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;basic_api/kernel_operator_mm_intf.h&quot;</code>。</p><p>负责完成普通矩阵计算所需的2D格式数据的搬运，以大小为512字节的数据分形为单位从Global Memory搬运至L1 Buffer（TPosition为A1/B1）。</p><h2 id="函数原型">函数原型<a id="zh-cn_topic_0000002567745223_section82039854412"></a><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">LoadData</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LoadData2DParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">loadDataParams</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<a id="zh-cn_topic_0000002567745223_section16128134420472"></a><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 通用参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor。<br>分形约束参考<a href="cube_compute_input_move_constraint.html">矩阵计算输入搬运约束</a>。<br>起始地址对齐约束参考矩阵计算输入搬运约束中的<a href="cube_compute_input_move_constraint.html">对齐约束</a>。<br>数据类型和src的数据类型保持一致。<br>支持的物理存储位置为L1 Buffer（TPosition为A1/B1）。</td></tr><tr><td>src</td><td>输入</td><td>源操作数，类型为GlobalTensor。<br>分形约束参考<a href="cube_compute_input_move_constraint.html">矩阵计算输入搬运约束</a>。<br>起始地址对齐约束参考矩阵计算输入搬运约束中的<a href="cube_compute_input_move_constraint.html">对齐约束</a>。<br>数据类型和dst的数据类型保持一致。<br>支持的物理存储位置为Global Memory（TPosition为GM）。</td></tr><tr><td>loadDataParams</td><td>输入</td><td>LoadData参数结构体，类型为LoadData2DParams，具体参考<a href="#zh-cn_topic_0000002567745223_table8955841508">表2</a>。</td></tr></tbody></table><p><strong>表2</strong> LoadData2DParams结构体内参数说明<a id="zh-cn_topic_0000002567745223_table8955841508"></a></p><table><thead><tr><th>参数名称</th><th>含义</th></tr></thead><tbody><tr><td>startIndex</td><td>分形矩阵ID，说明搬运起始位置为源操作数中第几个分形（0为源操作数中第1个分形矩阵）。取值范围：startIndex∈[0, 65535]。单位：512字节。默认为0。</td></tr><tr><td>repeatTimes</td><td>迭代次数，每个迭代可以处理512字节数据。取值范围：repeatTimes∈[0, 255]。<br><strong>注：repeatTimes = 0表示不执行搬运，该接口将被视为NOP（空操作）。</strong></td></tr><tr><td>srcStride</td><td>相邻迭代间，源操作数前一个分形与后一个分形<strong>起始地址</strong>的间隔，单位：512字节。取值范围：srcStride∈[0, 65535]。默认为0。<br><strong>注：srcStride = 0表示在连续的重复执行周期之间，重复获取相同的分形矩阵。</strong></td></tr><tr><td>sid</td><td>此参数用户无需关注，设置为0即可。</td></tr><tr><td>dstGap</td><td>相邻迭代间，目的操作数前一个分形<strong>结束地址</strong>与后一个分形<strong>起始地址</strong>的间隔，单位：512字节。取值范围：dstGap∈[0, 65535]。默认为0。<br><strong>注：dstGap = 0表示相邻repeat目的操作数起始地址间隔1个数据分形即连续存放。</strong></td></tr><tr><td>ifTranspose</td><td>是否启用转置功能，对每个分形矩阵进行转置，默认为false：<br>  • true：启用。<br>  • false：不启用。<br><strong>注：本通路场景下不支持转置，参数无意义，保持默认即可。</strong></td></tr><tr><td>addrMode</td><td>用于控制多次迭代场景下，源操作数中每一次迭代的分形矩阵索引ID是递增还是递减，0表示递增，下一次repeat index = startIndex + srcStride * repeatTimes。1表示递减，下一次repeat index = startIndex - srcStride * repeatTimes。</td></tr></tbody></table><h2 id="数据类型">数据类型<a id="zh-cn_topic_0000002567745223_section4219135304818"></a><a class="header-anchor" href="#数据类型">​</a></h2><div data-filter="950"><p>针对Ascend 950PR/Ascend 950DT，支持数据类型为：uint8_t、int8_t、uint16_t、int16_t、half、bfloat16_t、uint32_t、int32_t、float。</p></div><div data-filter="A3"><p>针对Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持数据类型为：b8、b16、b32。</p></div><div data-filter="910b"><p>针对Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持数据类型为：b8、b16、b32。</p></div><div data-filter="310b"><p>针对Atlas 200I/500 A2 推理产品，支持数据类型为：uint8_t、int8_t、uint16_t、int16_t、half、bfloat16_t、uint32_t、int32_t、float。</p></div><div data-filter="310p"><p>针对Atlas 推理系列产品AI Core，支持数据类型为：uint8_t、int8_t、uint16_t、int16_t、half。</p></div><div data-filter="910"><p>针对Atlas 训练系列产品，支持数据类型为：uint8_t、int8_t、uint16_t、int16_t、half。</p></div><div data-filter="x90"><p>针对Kirin X90，支持数据类型为：int8_t、half。</p></div><div data-filter="9030"><p>针对Kirin 9030，支持数据类型为：half。</p></div><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a id="zh-cn_topic_0000002567745223_section2045914466492"></a><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>操作数地址对齐要求请参见<a href="../../../general_description_and_constraints.html#section796754519912">通用地址对齐约束</a>。</li><li>本通路搬运过程中不支持转置。</li><li>目的地址必须32字节对齐。源地址必须1字节对齐，指令执行占用的流水为PIPE_MTE2。</li><li>当srcStride=0时，表示连续的repeat之间读取的源操作数中的同一块数据分形。</li></ul><div data-filter="910"><ul><li>针对Atlas 训练系列产品不支持dstGap设置参数。</li></ul></div><h2 id="调用示例">调用示例<a id="zh-cn_topic_0000002567745223_section088124295117"></a><a class="header-anchor" href="#调用示例">​</a></h2><p>如下示例中：在数据类型为half的场景下，通过调用LoadData接口完成GM-&gt;L1 Buffer的Nz2Nz数据搬运。</p><p>搬运过程的数据排布变化示意图如下：</p><p><img src="`+l+`" alt></p><p>示例代码片段如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// m=32, k=32, fractalShape[0] = 16,fractalShape[1] = 16, fractalSize = 256;</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">dstOffset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">fractalSize</span><span class="p">;</span>
<span class="kt">uint32_t</span><span class="w"> </span><span class="n">srcOffset</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">fractalSize</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LoadData2DParams</span><span class="w"> </span><span class="n">loadDataParams</span><span class="p">;</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">repeatTimes</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CeilDivision</span><span class="p">(</span><span class="n">k</span><span class="p">,</span><span class="w"> </span><span class="n">fractalShape</span><span class="p">[</span><span class="mi">1</span><span class="p">]);</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">srcStride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CeilDivision</span><span class="p">(</span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">fractalShape</span><span class="p">[</span><span class="mi">0</span><span class="p">]);</span>
<span class="n">loadDataParams</span><span class="p">.</span><span class="n">dstGap</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">CeilDivision</span><span class="p">(</span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">fractalShape</span><span class="p">[</span><span class="mi">0</span><span class="p">])</span><span class="w"> </span><span class="o">-</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="k">for</span><span class="w"> </span><span class="p">(</span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span><span class="w"> </span><span class="n">i</span><span class="w"> </span><span class="o">&lt;</span><span class="w"> </span><span class="n">CeilDivision</span><span class="p">(</span><span class="n">m</span><span class="p">,</span><span class="w"> </span><span class="n">fractalShape</span><span class="p">[</span><span class="mi">0</span><span class="p">]);</span><span class="w"> </span><span class="o">++</span><span class="n">i</span><span class="p">)</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">AscendC</span><span class="o">::</span><span class="n">LoadData</span><span class="p">(</span><span class="n">a1Local</span><span class="p">[</span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">dstOffset</span><span class="p">],</span><span class="w"> </span><span class="n">aGM</span><span class="p">[</span><span class="n">i</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">srcOffset</span><span class="p">],</span><span class="w"> </span><span class="n">loadDataParams</span><span class="p">);</span>
<span class="p">}</span>
</code></pre></div></article></div>`,1)])])}const v=s(c,[["render",i]]);export{u as __pageData,v as default};
